-- Exact reviewed topology, used by fixed assembly and synthetic proof only.
CREATE OR REPLACE FUNCTION pg_temp.employee_tables() RETURNS text[] LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,pg_temp AS $objects$ SELECT ARRAY['private.employee_records','private.employee_number_claims','private.employee_account_links','private.employee_episodes','private.employee_reporting_revisions','private.employee_reporting_intervals','private.employee_audit_events','private.employee_operations','private.employee_settings','private.employee_reporting_guard']::text[] $objects$;
CREATE OR REPLACE FUNCTION pg_temp.employee_entrypoints() RETURNS text[] LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,pg_temp AS $objects$ SELECT ARRAY['public.employee_context_v1()','private.employee_context_impl_v1()','public.employee_page_v1(text,text,integer,integer)','private.employee_page_impl_v1(text,text,integer,integer)','public.employee_detail_v1(uuid)','private.employee_detail_impl_v1(uuid)','public.employee_audit_v1(uuid,integer,integer)','private.employee_audit_impl_v1(uuid,integer,integer)','public.employee_account_candidates_v1(text,integer,integer)','private.employee_account_candidates_impl_v1(text,integer,integer)','public.employee_preview_v1(uuid,bigint,text,jsonb,text,date,text)','private.employee_preview_impl_v1(uuid,bigint,text,jsonb,text,date,text)','public.employee_command_v1(uuid,uuid,bigint,text,jsonb,text,date,text,text)','private.employee_command_impl_v1(uuid,uuid,bigint,text,jsonb,text,date,text,text)','public.employee_operation_v1(uuid,text)','private.employee_operation_impl_v1(uuid,text)']::text[] $objects$;
CREATE OR REPLACE FUNCTION pg_temp.employee_helpers() RETURNS text[] LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,pg_temp AS $objects$ SELECT ARRAY['private.employee_timezone_valid(text)','private.employee_require_director()','private.employee_read_guard(text,integer,integer)','private.employee_fields(private.employee_records)','private.employee_audit_projection(jsonb)','private.employee_trim(text)','private.employee_text(text,integer,boolean)','private.employee_date(jsonb)','private.employee_hash(jsonb)','private.employee_request(uuid,bigint,text,jsonb,text,date,text)','private.employee_lock_actor()','private.employee_lock_operation(uuid,uuid)','private.employee_prepare(jsonb)','private.employee_reporting_request(uuid,jsonb)','private.employee_reporting_prepare(jsonb)','private.employee_reporting_apply(uuid,jsonb,uuid,text)']::text[] $objects$;
CREATE OR REPLACE FUNCTION pg_temp.employee_owned_object(class_id oid, object_id oid) RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog,pg_temp AS $$
 SELECT coalesce(CASE class_id
 WHEN 'pg_class'::regclass THEN EXISTS(SELECT 1 FROM pg_class c WHERE c.oid=object_id AND (c.oid=ANY(ARRAY(SELECT to_regclass(x) FROM unnest(pg_temp.employee_tables())x)) OR c.oid IN(SELECT indexrelid FROM pg_index WHERE indrelid=ANY(ARRAY(SELECT to_regclass(x) FROM unnest(pg_temp.employee_tables())x)))))
 WHEN 'pg_proc'::regclass THEN object_id=ANY(ARRAY(SELECT to_regprocedure(x) FROM unnest(pg_temp.employee_entrypoints()||pg_temp.employee_helpers())x))
 WHEN 'pg_type'::regclass THEN EXISTS(SELECT 1 FROM pg_type t WHERE t.oid=object_id AND (t.typrelid=ANY(ARRAY(SELECT to_regclass(x) FROM unnest(pg_temp.employee_tables())x)) OR t.typelem IN(SELECT c.reltype FROM pg_class c WHERE c.oid=ANY(ARRAY(SELECT to_regclass(x) FROM unnest(pg_temp.employee_tables())x)))))
 WHEN 'pg_constraint'::regclass THEN EXISTS(SELECT 1 FROM pg_constraint c WHERE c.oid=object_id AND c.conrelid=ANY(ARRAY(SELECT to_regclass(x) FROM unnest(pg_temp.employee_tables())x)))
 WHEN 'pg_trigger'::regclass THEN EXISTS(SELECT 1 FROM pg_trigger t JOIN pg_constraint c ON c.oid=t.tgconstraint WHERE t.oid=object_id AND c.conrelid=ANY(ARRAY(SELECT to_regclass(x) FROM unnest(pg_temp.employee_tables())x)))
 WHEN 'pg_attrdef'::regclass THEN EXISTS(SELECT 1 FROM pg_attrdef d WHERE d.oid=object_id AND d.adrelid=ANY(ARRAY(SELECT to_regclass(x) FROM unnest(pg_temp.employee_tables())x)))
 ELSE false END,false)
$$;
CREATE OR REPLACE FUNCTION pg_temp.employee_acl(a aclitem[]) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog,pg_temp AS $$
 SELECT CASE WHEN a IS NULL THEN 'null'::jsonb ELSE coalesce((SELECT jsonb_agg(jsonb_build_array(pg_get_userbyid(grantor),CASE WHEN grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(grantee) END,privilege_type,is_grantable) ORDER BY grantor,grantee,privilege_type,is_grantable) FROM aclexplode(a)),'[]'::jsonb) END
$$;
